cases.script:
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null
for mode in format pretty oneline default disabled; do
  case $mode in
    format) set -- --show-signature --format=%H ;;
    pretty) set -- --show-signature --pretty=format:%H ;;
    oneline) set -- --show-signature --oneline ;;
    default) set -- --show-signature ;;
    disabled) set -- --show-signature --no-show-signature --format=%H ;;
  esac
  git -C signed -c gpg.format=ssh -c gpg.ssh.allowedSignersFile="$HOME/signers" log -1 "$@" >"$HOME/log-$mode.out" 2>"$HOME/log-$mode.err"; rc=$?
  sig=no
  if /usr/bin/grep -F 'Good "git" signature for fixture@example.test' "$HOME/log-$mode.out" >/dev/null; then sig=yes; fi
  printf '%s rc=%s signature=%s\n' "$mode" "$rc" "$sig"
done
/usr/bin/rm -rf signed
